    "question": "Warum sollten Sie auf das Alter Ihrer Anhängerreifen achten?",
    "explanation": "Es gibt keine gesetzliche Altersgrenze für den Reifentausch. Wenn die Reifen älter als sechs Jahre sind, sollten Sie deren Zustand genau im Auge behalten. Die Reifenalterung wird häufig durch kleine Risse, die in der Reifenseitenwand auftreten, erkannt. Außerdem wird der Reifen härter und kann dadurch weniger Kräfte übertragen.",
